patch:
diff --git a/repro-use-strict.js b/repro-use-strict.js
new file mode 100644
index 0000000..2645e33
--- /dev/null
+++ b/repro-use-strict.js
@@ -0,0 +1,39 @@
+/**
+ * Reproduction check: `no-unused-expressions` must not report a `'use strict'`
+ * directive (Espree, default parser), even with `ecmaVersion: 3`.
+ *
+ * Run from the repo root: node repro-use-strict.js
+ * Exits 1 while the bug is present, 0 once `'use strict'` is accepted.
+ */
+"use strict";
+
+const { ESLint } = require("./lib/api");
+
+const code = "'use strict';\nvar a = 1;\n";
+
+(async () => {
+	const eslint = new ESLint({
+		cwd: __dirname,
+		overrideConfigFile: true,
+		overrideConfig: {
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+			rules: { "no-unused-expressions": "error" },
+		},
+	});
+
+	const [result] = await eslint.lintText(code, {
+		filePath: "repro-use-strict-input.js",
+	});
+
+	console.log(`ESLint ${ESLint.version}, ecmaVersion 3, input: ${JSON.stringify(code)}`);
+	for (const m of result.messages) {
+		console.log(`  ${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
+	}
+
+	if (result.messages.length > 0) {
+		console.error("FAIL: expected no problems for 'use strict'");
+		process.exitCode = 1;
+	} else {
+		console.log("OK: no problems reported");
+	}
+})();
